-- | A block that holds interactive elements such as buttons and menus.
--
-- <https://docs.slack.dev/reference/block-kit/blocks/actions-block>
newtype ActionsBlock = CheckedActionsBlock ActionsBlockFields deriving (Eq, Show)

-- | Editable construction input. Call 'buildActionsBlock' before encoding.
