  { -- | Adds interactive elements in display order.
    actionsBlockElements :: [Element],
    -- | Sets a unique identifier for this block. Slack returns it in interaction payloads, so use a stable value when you need to find the block again.
    actionsBlockBlockId :: Maybe (Text),
    -- | Unmodeled extension fields. Reserved and modeled keys are rejected.
    actionsBlockExtensions :: Map Text Value
  }
  deriving (Eq, Show)

actionsBlock :: [Element] -> ActionsBlockFields
actionsBlock arg0 = ActionsBlockFields (arg0) (Nothing) (Map.empty)

inspectActionsBlock :: ActionsBlock -> ActionsBlockFields
inspectActionsBlock (CheckedActionsBlock fields) = fields

buildActionsBlock :: ActionsBlockFields -> Result ActionsBlock
buildActionsBlock fields = do
  checkExtensions ["elements", "block_id"] (actionsBlockExtensions fields)
  validateFields "ActionsBlock" (wireActionsBlock fields)
  pure (CheckedActionsBlock fields)

wireActionsBlock :: ActionsBlockFields -> Value
wireActionsBlock fields =
  object $
    ["type" .= ("actions" :: Text)] <> ["elements" .= (actionsBlockElements fields)] <> optional "block_id" (actionsBlockBlockId fields) <> extensionPairs (actionsBlockExtensions fields)

instance ToJSON ActionsBlock where toJSON (CheckedActionsBlock fields) = wireActionsBlock fields

instance FromSlackJSON ActionsBlock where
  fromSlackJSON value = do
    fields <- wireObject "actions" value
    parsedElements <- required "elements" fields
    parsedBlockId <- optionalField "block_id" fields
    buildActionsBlock (ActionsBlockFields parsedElements parsedBlockId (remaining ["elements", "block_id"] fields))

instance FromJSON ActionsBlock where parseJSON = checkedParser

